  async function loadDocuments(){const requestedKind=documentKind;try{const result=await api(`/api/documents?kind=${requestedKind}`);if(requestedKind!==documentKind)return;documents=result.documents;renderDocuments();}catch(error){if(requestedKind!==documentKind)return;const message=requestedKind==='fatd'&&/tipo documental|área documental|rota não encontrada/i.test(error.message)?'Reinicie o servidor local do SIGASE para carregar o suporte a FATD.':error.message;$('#document-list').innerHTML=empty('Arquivo indisponível',esc(message));}}
  function documentCardMarkup(d,label,symbol){const ref=d.kind==='fatd'?`Processo ${esc(d.bulletin_number)}`:d.kind==='pernoite'?`Revista do recolher · ${esc(longDate(d.data.serviceDate||d.document_date,false))}`:`Boletim Nr ${esc(d.bulletin_number)}`;return `<article class="document-card"><div class="doc-symbol">${symbol}</div><div class="doc-card-main"><strong>${label} · ${ref}</strong><small>${formatUnitDate(d.document_date)} · ${esc(d.data.militaryName||d.data.mainSigner||d.data.unit||'Unidade de sistema')}</small></div><div class="doc-card-actions"><button class="button secondary" data-doc-view="${d.id}">Visualizar</button><button class="button secondary" data-doc-print="${d.id}">Imprimir / PDF</button>${canEditDocuments?`<button class="button secondary" data-doc-edit="${d.id}">Editar</button><button class="button delete-button" data-delete-kind="document" data-delete-id="${d.id}">Excluir</button>`:''}</div></article>`;}
  function renderDocuments(){const titles={aditamento:['Aditamentos','Registro para cada dia de expediente.','aditamento','A'],pernoite:['Pernoites','Registro do recolher para todos os dias.','pernoite','P'],fatd:['FATD','Formulários de apuração de transgressão disciplinar.','FATD','F']},[title,subtitle,label,symbol]=titles[documentKind];$('#document-area-title').textContent=title;$('#document-area-subtitle').textContent=subtitle;$('#new-document').textContent=`＋ Novo ${label}`;document.querySelectorAll('.document-kind').forEach(b=>b.classList.toggle('active',b.dataset.kind===documentKind));if(!documents.length){$('#document-list').innerHTML=empty(`Nenhum registro de ${title.toLowerCase()} salvo`,canEditDocuments?'Crie o primeiro documento desta área.':'Os documentos salvos aparecerão aqui.');return;}if(documentKind==='fatd'){$('#document-list').innerHTML=documents.map(d=>documentCardMarkup(d,label,symbol)).join('');return;}const grouped=new Map();for(const doc of documents){const dateValue=doc.document_date||doc.data?.serviceDate||'';const date=dateValue?new Date(`${dateValue}T12:00:00`):new Date(0);const year=String(date.getFullYear()),monthKey=String(date.getMonth()+1).padStart(2,'0'),monthName=new Intl.DateTimeFormat('pt-BR',{month:'long'}).format(date);if(!grouped.has(year))grouped.set(year,new Map());const months=grouped.get(year);if(!months.has(monthKey))months.set(monthKey,{name:monthName,documents:[]});months.get(monthKey).documents.push(doc);}$('#document-list').innerHTML=[...grouped.entries()].sort(([a],[b])=>b.localeCompare(a)).map(([year,months])=>{const count=[...months.values()].reduce((total,month)=>total+month.documents.length,0);return `<details class="archive-folder"><summary><span class="folder-icon">▰</span><strong>${year}</strong><small>${count} ${count===1?'documento':'documentos'}</small></summary><div class="folder-contents">${[...months.entries()].sort(([a],[b])=>b.localeCompare(a)).map(([key,month])=>`<details class="archive-folder month-folder"><summary><span class="folder-icon">▰</span><strong>${month.name}</strong><small>${month.documents.length} ${month.documents.length===1?'documento':'documentos'}</small></summary><div class="folder-contents">${month.documents.sort((a,b)=>(b.document_date||'').localeCompare(a.document_date||'')).map(doc=>documentCardMarkup(doc,label,symbol)).join('')}</div></details>`).join('')}</div></details>`;}).join('');}
