  function canonicalForceRank(rank){const key=String(rank||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[º°]/g,'o').replace(/[^a-z0-9]/g,''),aliases={capitao:'Cap',tenente:'1º Ten','1oten':'1º Ten','1otenente':'1º Ten','2oten':'2º Ten','2otenente':'2º Ten',subtenente:'STen',subten:'STen',sten:'STen','1osgt':'1º Sgt','1osargento':'1º Sgt','1sargento':'1º Sgt','2osgt':'2º Sgt','2osargento':'2º Sgt','2sargento':'2º Sgt','3osgt':'3º Sgt','3osargento':'3º Sgt','3sargento':'3º Sgt',cb:'Cb EP',cabo:'Cb EP',cbep:'Cb EP',caboep:'Cb EP',sd:'Sd EP',soldado:'Sd EP',sdep:'Sd EP',soldadoep:'Sd EP',sdev:'Sd EV',soldadoev:'Sd EV'};return aliases[key]||rank;}
