  function forceMapCard(map){return `<article class="document-card"><div class="doc-symbol">MF</div><div class="doc-card-main"><strong>Mapa da Força - 3ªBO</strong><small>${formatUnitDate(map.activity_date)} · ${map.data.rows.length} militares</small></div><div class="doc-card-actions"><button class="button secondary" data-force-view="${map.id}">Visualizar</button><button class="button secondary" data-force-print="${map.id}">Imprimir / PDF</button>${canEditDocuments?`<button class="button secondary" data-force-edit="${map.id}">Editar</button><button class="button delete-button" data-delete-kind="force-map" data-delete-id="${map.id}">Excluir</button>`:''}</div></article>`;}
