  function forceMapTable(rows,startIndex=0,editor=false){const rowHtml=(person,index)=>editor?`<tr data-force-row data-person-id="${Number(person.person_id)}" data-rank="${esc(person.rank)}" data-war-name="${esc(person.war_name)}"><td>${startIndex+index+1}</td><td>${esc(person.rank)} ${esc(person.war_name)}</td><td><select data-force-observation aria-label="Observação de ${esc(person.war_name)}">${forceObservations.map(value=>`<option value="${esc(value)}" ${person.observation===value?'selected':''}>${value?esc(value):'Presente'}</option>`).join('')}</select><input class="force-other-input ${person.observation==='Outros'?'':'hidden'}" data-force-other value="${esc(person.other_text||'')}" maxlength="80" placeholder="Descreva"></td></tr>`:`<tr><td>${startIndex+index+1}</td><td>${esc(person.rank)} ${esc(person.war_name)}</td><td>${person.observation==='Outros'?esc(person.other_text||'Outros'):esc(person.observation||'')}</td></tr>`;return `<table class="force-map-table ${editor?'force-map-edit-table':''}"><colgroup><col><col><col></colgroup><thead><tr><th>Ord</th><th>P/G · Nome de guerra</th><th>Obs</th></tr></thead><tbody>${rows.map(rowHtml).join('')}</tbody></table>`;}
