  function openForceMap(id){const map=forceMaps.find(item=>item.id===Number(id));if(!map)return;const markup=forceMapMarkup(map);showModal(`<style>${forceMapPrintStyles}</style><div class="modal-head"><div><p class="eyebrow">MAPA DA FORÇA · ${formatUnitDate(map.activity_date)}</p><h2>Mapa arquivado</h2></div><button class="close-button" data-close>×</button></div><div class="force-map-preview">${markup}</div><div class="detail-actions"><button class="button secondary" data-close>Fechar</button><button class="button secondary" data-force-print="${map.id}">Imprimir / PDF</button>${canEditDocuments?`<button class="button primary" data-force-edit="${map.id}">Editar</button><button class="button delete-button" data-delete-kind="force-map" data-delete-id="${map.id}">Excluir</button>`:''}</div>`,true);}
  function printForceMap(id){const map=forceMaps.find(item=>item.id===Number(id));if(!map)return;const old=document.querySelector('#sigase-print-host');if(old)old.remove();const host=document.createElement('main');host.id='sigase-print-host';host.innerHTML=`<style>${forceMapPrintStyles}@media screen{#sigase-print-host{display:none!important}}@media print{html,body{width:auto!important;height:auto!important;overflow:visible!important;background:#fff!important;margin:0!important;padding:0!important}body>*:not(#sigase-print-host){display:none!important}#sigase-print-host{display:block!important;position:static!important;visibility:visible!important;opacity:1!important;width:auto!important;height:auto!important;overflow:visible!important;background:#fff!important;color:#111!important;padding:0!important;margin:0!important}}</style>${forceMapMarkup(map)}`;document.body.appendChild(host);const cleanup=()=>{host.remove();window.removeEventListener('afterprint',cleanup);};window.addEventListener('afterprint',cleanup,{once:true});try{window.focus();window.print();setTimeout(cleanup,120000);}catch(error){cleanup();notify('Não foi possível abrir a impressão. Tente novamente.');}}
  const forceMapPrintStyles=`@page{size:A4 portrait;margin:6mm 7mm}*{box-sizing:border-box}.force-map-paper{font-family:Arial,sans-serif;color:#111;width:100%;max-width:none;margin:0 auto}.force-map-paper header{text-align:center;margin:0 0 2mm}.force-map-paper h2{font:700 11pt Arial,sans-serif;margin:0 0 1mm}.force-map-paper header p{font:8pt Arial,sans-serif;margin:0}.force-map-columns{display:grid;grid-template-columns:1fr 1fr;gap:3mm;align-items:start}.force-map-editor-columns{gap:10px}.force-map-table{width:100%;border-collapse:collapse;table-layout:fixed;font:7pt Arial,sans-serif;line-height:1.02}.force-map-table col:nth-child(1){width:8%}.force-map-table col:nth-child(2){width:63%}.force-map-table col:nth-child(3){width:29%}.force-map-table th,.force-map-table td{border:.35pt solid #222;padding:.65mm .8mm;vertical-align:middle}.force-map-table th{font-weight:700;text-align:left}.force-map-table td:first-child,.force-map-table th:first-child{text-align:center}.force-map-table tbody td{height:4.7mm}.force-map-edit-table td{padding:1mm}.force-map-edit-table select,.force-map-edit-table input{width:100%;min-width:0;border:1px solid #dfe4df;border-radius:4px;padding:3px;font:8px Arial,sans-serif}.force-other-input{margin-top:3px}.force-map-preview{overflow:auto;max-height:72vh;background:#eef0ed;padding:12px}.force-map-preview .force-map-paper{width:190mm;min-height:277mm;background:#fff;padding:6mm 7mm;margin:auto;box-shadow:0 2px 12px #0002}@media print{.force-map-preview{overflow:visible;max-height:none;padding:0;background:#fff}.force-map-preview .force-map-paper{width:100%;min-height:0;padding:0;box-shadow:none}}`;
  function docRowEditor(group,row,index){const adit=group==='dutyRows';return `<div class="doc-edit-row" data-row-group="${group}"><div class="form-field"><label>${adit?'Serviço/função':'Graduação'}</label><input data-field="${adit?'label':'rank'}" value="${esc(row[adit?'label':'rank']||'')}" placeholder="${adit?'Ex.: Sargento de Dia':'Ex.: SOLDADOS'}"></div>${adit?'':`<div class="form-field"><label>Serviço/destino</label><input data-field="description" value="${esc(row.description||'')}" placeholder="Ex.: Guarda ao Quartel"></div>`}<div class="form-field"><label>${adit?'Posto/graduação':'Militares em forma'}</label><input data-field="${adit?'rank':'personnel'}" value="${esc(row[adit?'rank':'personnel']||'')}" placeholder="${adit?'Ex.: Sd.':'Nomes informados'}"></div>${adit?`<div class="form-field"><label>Militares / observação</label><textarea data-field="personnel" rows="2">${esc(row.personnel||'')}</textarea></div>`:`<div class="form-field"><label>Quantidade</label><input data-field="count" type="number" min="0" max="999" value="${Number(row.count)||0}"></div>`}<button type="button" class="remove-row" title="Remover linha" aria-label="Remover linha">×</button></div>`;}
  function pernoiteGroups(d,key){const current=d[key==='formation'?'formationGroups':'destinationGroups'];if(Array.isArray(current))return current;const ranks=key==='formation'?['SARGENTOS','CABOS','SOLDADOS']:['CABOS','SOLDADOS','DISPENSA MÉDICA'],legacy=d[key]||[];return ranks.map(rank=>{const matches=legacy.filter(row=>{const label=`${row.rank||''} ${row.description||''}`.toUpperCase();return rank==='DISPENSA MÉDICA'?label.includes('DISPENSA')||/SD\s*(EP|EV)/.test(label):label.includes(rank);});let services=matches.map(row=>rank==='DISPENSA MÉDICA'?{rankLabel:row.description||'Sd.',personnel:row.personnel||'',count:Math.max(1,Number(row.count)||1)}:{description:row.description||'',personnel:row.personnel||'',count:Number(row.count)||0});if(!services.length)services=[rank==='DISPENSA MÉDICA'?{rankLabel:'',personnel:'',count:1}:{description:'',personnel:'',count:0}];return {rank,services};});}
