  function pernoiteForm(existing=null){const editing=!!existing,d=existing?.data||overnightDefaults(),formation=pernoiteGroups(d,'formation'),destinations=pernoiteGroups(d,'destinations');documentKind='pernoite';showModal(`<div class="modal-head"><div><p class="eyebrow">ÁREA DOCUMENTAL · PERNOITE</p><h2>${editing?'Editar':'Novo'} pernoite</h2><p>Registre o efetivo em forma e os demais destinos.</p></div><button class="close-button" data-close>×</button></div><form id="pernoite-form" novalidate><div class="form-body"><div class="doc-form-section"><h3>Data do pernoite</h3><div class="form-field"><label>Data da revista *</label><input type="date" name="serviceDate" value="${esc(d.serviceDate||existing?.document_date||'')}"><small class="error" data-error="serviceDate"></small></div></div><div class="doc-form-section"><div class="doc-section-title"><h3>Em forma</h3></div><p class="doc-help muted">As graduações são fixas. Adicione linhas de serviço e preencha a quantidade de militares em cada uma.</p><div class="pernoite-editor">${formation.map(group=>pernoiteGroupMarkup('formation',group)).join('')}</div></div><div class="doc-form-section"><h3>Outros destinos</h3><p class="doc-help muted">Cabos e soldados permitem serviço/destino e quantidade. Em dispensa médica, informe a graduação e o nome de cada militar.</p><div class="pernoite-editor">${destinations.map(group=>pernoiteGroupMarkup('destinations',group)).join('')}</div></div><div class="doc-form-section"><h3>Assinatura do comandante</h3><div class="form-field"><label>Nome do comandante *</label><input name="commander" value="${esc(d.commander||'')}"><small class="error" data-error="commander"></small></div><label class="check-line"><input type="checkbox" name="commanderActing" ${d.commanderActing?'checked':''}><span>Respondendo — usar “Resp. Cmt 3ª BO”</span></label></div><div class="doc-form-section"><h3>Assinatura do sargenteante</h3><div class="form-row"><div class="form-field"><label>Nome do sargenteante *</label><input name="mainSigner" value="${esc(d.mainSigner||'')}"><small class="error" data-error="mainSigner"></small></div><div class="form-field"><label>Data da assinatura *</label><input type="date" name="signatureDate" value="${esc(d.signatureDate||d.serviceDate||'')}"><small class="error" data-error="signatureDate"></small></div></div><label class="check-line"><input type="checkbox" name="mainResponding" ${d.mainResponding?'checked':''}><span>Respondendo — usar “Resp. Sargenteante da 3ªBia O”</span></label></div><div class="doc-form-section"><h3>Quadro de revista do recolher</h3><div class="form-field"><label>Graduação e nome do Sgt de Dia</label><input name="sergeantOfDay" value="${esc(d.sergeantOfDay||'')}"></div><p class="form-hint">A assinatura do Oficial de Dia, os espaços de data e as observações ficam para preenchimento à caneta.</p></div><p class="form-hint">Revise os dados antes de salvar o formulário.</p></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button primary">${editing?'Salvar alterações':'Salvar pernoite'}</button></div></form>`,true);
    const form=$('#pernoite-form'),updateSubtotals=()=>form.querySelectorAll('.pernoite-editor-group').forEach(group=>{const total=[...group.querySelectorAll('.pernoite-editor-row')].reduce((sum,row)=>{if(group.dataset.rank==='DISPENSA MÉDICA')return sum+(row.querySelector('[data-pfield="rankLabel"]')?.value.trim()&&row.querySelector('[data-pfield="personnel"]')?.value.trim()?1:0);return sum+(Number(row.querySelector('[data-pfield="count"]')?.value)||0);},0);const target=group.querySelector('[data-subtotal]');if(target)target.textContent=total;});
    form.addEventListener('click',e=>{const add=e.target.closest('[data-pernoite-add]');if(add){const group=[...form.querySelectorAll('.pernoite-editor-group')].find(x=>x.dataset.pgroup===add.dataset.pernoiteAdd&&x.dataset.rank===add.dataset.rank);if(group)group.querySelector('.pernoite-editor-rows').insertAdjacentHTML('beforeend',pernoiteRowMarkup(group.dataset.pgroup,group.dataset.rank,group.dataset.rank==='DISPENSA MÉDICA'?{count:1}:{}));updateSubtotals();}const remove=e.target.closest('[data-pernoite-remove]');if(remove){const rows=remove.closest('.pernoite-editor-rows');if(rows.children.length>1)remove.closest('.pernoite-editor-row').remove();updateSubtotals();}});form.addEventListener('input',updateSubtotals);updateSubtotals();
    form.addEventListener('submit',async e=>{e.preventDefault();const val=name=>String(form.elements[name]?.value||'').trim(),serviceDate=val('serviceDate'),signatureDate=val('signatureDate'),commander=val('commander'),mainSigner=val('mainSigner');let valid=true;for(const [key,value] of [['serviceDate',serviceDate],['signatureDate',signatureDate],['commander',commander],['mainSigner',mainSigner]]){const error=form.querySelector(`[data-error="${key}"]`);if(error)error.textContent=value?'':'Preencha este campo.';if(!value){form.elements[key].classList.add('invalid');valid=false;}else form.elements[key].classList.remove('invalid');}if(!valid){notify('Preencha os campos obrigatórios destacados.');form.querySelector('.invalid')?.focus();return;}const readGroups=type=>[...form.querySelectorAll(`.pernoite-editor-group[data-pgroup="${type}"]`)].map(group=>({rank:group.dataset.rank,services:[...group.querySelectorAll('.pernoite-editor-row')].map(row=>{const item=Object.fromEntries([...row.querySelectorAll('[data-pfield]')].map(input=>[input.dataset.pfield,input.type==='number'||input.type==='hidden'?Number(input.value)||0:input.value.trim()]));if(group.dataset.rank==='DISPENSA MÉDICA')item.count=item.rankLabel&&item.personnel?1:0;return item;})}));const content={serviceDate,signatureDate,commander,commanderActing:form.elements.commanderActing.checked,formationGroups:readGroups('formation'),destinationGroups:readGroups('destinations'),mainSigner,mainResponding:form.elements.mainResponding.checked,sergeantOfDay:val('sergeantOfDay'),city:d.city||'Bagé-RS'};const body={kind:'pernoite',bulletin_number:`P-${serviceDate}`,document_date:serviceDate,data:content};try{await api(editing?`/api/documents/${existing.id}`:'/api/documents',{method:editing?'PUT':'POST',body});closeModal();await loadDocuments();notify(editing?'Pernoite atualizado.':'Pernoite salvo no arquivo.');}catch(error){notify(error.message);}});}
