  function fatdDefaults(){const now=new Date(),year=now.getFullYear(),max=documents.reduce((n,d)=>{const m=String(d.bulletin_number||'').match(/^(\d+)/);return Math.max(n,m?Number(m[1]):0);},0);return {process_number:`${String(max+1).padStart(3,'0')}/${year}`,date:`${year}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`,militaryRank:'',militaryId:'',militaryName:'',militarySubunit:'',participantRank:'',participantId:'',participantName:'',participantSubunit:'',report:'',authorityRank:'',authorityName:'',authoritySubunit:'',authorityRole:'',publicationNumber:'',publicationDate:''};}
  function fatdForm(existing=null){const editing=!!existing,d=existing?.data||fatdDefaults();documentKind='fatd';showModal(`<div class="modal-head"><div><p class="eyebrow">ÁREA DOCUMENTAL · FATD</p><h2>${editing?'Editar':'Novo'} formulário de apuração</h2><p>Preencha os campos necessários para emissão do formulário.</p></div><button class="close-button" data-close>×</button></div><form id="fatd-form" novalidate><div class="form-body"><div class="doc-form-section"><h3>Processo e data</h3><div class="form-row"><div class="form-field"><label>Número do processo *</label><input name="process_number" maxlength="40" value="${esc(existing?.bulletin_number||d.process_number||'')}"><small class="form-hint">Sugestão baseada no último FATD salvo; você pode alterar.</small><small class="error" data-error="process_number"></small></div><div class="form-field"><label>Data *</label><input name="date" type="date" value="${esc(d.date||existing?.document_date||'')}"><small class="error" data-error="date"></small></div></div></div><div class="doc-form-section"><h3>Identificação do militar arrolado</h3><div class="form-row"><div class="form-field"><label>Grau hierárquico *</label><input name="militaryRank" value="${esc(d.militaryRank||'')}"></div><div class="form-field"><label>IDT / CPF *</label><input name="militaryId" value="${esc(d.militaryId||'')}"></div></div><div class="form-field"><label>Nome completo *</label><input name="militaryName" value="${esc(d.militaryName||'')}"></div><div class="form-field"><label>Subunidade / OM *</label><input name="militarySubunit" value="${esc(d.militarySubunit||'')}"></div></div><div class="doc-form-section"><h3>Identificação do participante</h3><div class="form-row"><div class="form-field"><label>Grau hierárquico *</label><input name="participantRank" value="${esc(d.participantRank||'')}"></div><div class="form-field"><label>NR / IDT *</label><input name="participantId" value="${esc(d.participantId||'')}"></div></div><div class="form-field"><label>Nome completo *</label><input name="participantName" value="${esc(d.participantName||'')}"></div><div class="form-field"><label>Subunidade / OM *</label><input name="participantSubunit" value="${esc(d.participantSubunit||'')}"></div></div><div class="doc-form-section"><h3>Relato do fato</h3><div class="form-field"><label>Relato *</label><textarea name="report" rows="6">${esc(d.report||'')}</textarea><small class="error" data-error="report"></small></div><p class="form-hint">O nome e o grau hierárquico abaixo do relato serão os do participante.</p></div><div class="doc-form-section"><h3>Decisão da autoridade</h3><div class="form-row"><div class="form-field"><label>Grau hierárquico da autoridade *</label><input name="authorityRank" value="${esc(d.authorityRank||'')}"></div><div class="form-field"><label>Nome completo da autoridade *</label><input name="authorityName" value="${esc(d.authorityName||'')}"></div></div><div class="form-field"><label>Subunidade / OM</label><input name="authoritySubunit" value="${esc(d.authoritySubunit||'')}"></div><div class="form-field"><label>Função / cargo</label><input name="authorityRole" value="${esc(d.authorityRole||'')}"></div><p class="form-hint">A data da decisão e a publicação no BI permanecem para preenchimento manuscrito.</p></div><p class="form-hint">A justificativa, as datas manuscritas e o número do BI ficam em branco na impressão, conforme o modelo.</p></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button primary">${editing?'Salvar alterações':'Salvar FATD'}</button></div></form>`,true);
    $('#fatd-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,keys=['process_number','date','militaryRank','militaryId','militaryName','militarySubunit','participantRank','participantId','participantName','participantSubunit','report','authorityRank','authorityName'],content={};for(const key of keys)content[key]=String(form.elements[key].value||'').trim();content.authorityRole=String(form.elements.authorityRole.value||'').trim();content.authoritySubunit=String(form.elements.authoritySubunit.value||'').trim();let valid=true;for(const key of keys){const field=form.elements[key],error=form.querySelector(`[data-error="${key}"]`);if(error)error.textContent='';if(!content[key]){if(error)error.textContent='Preencha este campo.';field?.classList.add('invalid');valid=false;}else field?.classList.remove('invalid');}if(!valid){notify('Preencha os campos obrigatórios destacados.');form.querySelector('.invalid')?.focus();return;}const body={kind:'fatd',bulletin_number:content.process_number,document_date:content.date,data:content};try{const result=await api(editing?`/api/documents/${existing.id}`:'/api/documents',{method:editing?'PUT':'POST',body});closeModal();await loadDocuments();notify(editing?'FATD atualizado.':'FATD salvo no arquivo.');}catch(error){const message=/tipo documental inválido/i.test(error.message)?'O servidor local está desatualizado. Encerre-o e execute python server.py novamente para carregar o suporte a FATD.':error.message;notify(message);}});}
  function appendDocRow(group,row){const target=$(`#${group==='dutyRows'?'duty-row-list':group==='formation'?'formation-row-list':'destinations-row-list'}`);if(!target)return;target.insertAdjacentHTML('beforeend',docRowEditor(group,row,target.children.length));bindRemoveRows();}
  function bindRemoveRows(){document.querySelectorAll('.remove-row').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound='1';b.addEventListener('click',()=>b.closest('.doc-edit-row').remove());});}
