  function openDocument(id){const d=documents.find(x=>x.id===Number(id));if(!d)return;let markup;try{markup=renderDocumentMarkup(d);}catch(error){console.error('Falha ao montar prévia do documento:',error);notify('Não foi possível abrir a prévia deste documento. Verifique os dados salvos e tente novamente.');return;}const docTitle=d.kind==='fatd'?'FATD · PROCESSO':'DOCUMENTO · BOLETIM NR';showModal(`<style>${printStyles}</style><div class="modal-head"><div><p class="eyebrow">${docTitle} ${esc(d.bulletin_number)}</p><h2>Documento arquivado</h2></div><button class="close-button" data-close>×</button></div><div class="document-preview-wrap">${markup}</div><div class="detail-actions"><button class="button secondary" data-close>Fechar</button><button class="button secondary" data-doc-print="${d.id}">Imprimir / PDF</button>${canEditDocuments?`<button class="button primary" data-doc-edit="${d.id}">Editar</button><button class="button delete-button" data-delete-kind="document" data-delete-id="${d.id}">Excluir</button>`:''}</div>`,true);}
  function longDate(value,weekday=true){if(!value)return '________________';const d=new Date(`${value}T12:00:00`),dateText=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',year:'numeric'}).format(d);return weekday?`${dateText} (${new Intl.DateTimeFormat('pt-BR',{weekday:'long'}).format(d)})`:dateText;}
  const cellText=v=>esc(v||'').replace(/\n/g,'<br>');
  function aditamentoMarkup(doc){const d=doc.data||{},days=normalizeAditDays(d),notices=d.notices||{},parts=[['instruction','2ª PARTE – INSTRUÇÃO'],['general','3ª PARTE – ASSUNTOS GERAIS E ADMINISTRATIVOS'],['discipline','4ª PARTE – JUSTIÇA E DISCIPLINA']],dayMarkup=days.map((day,index)=>{const rows=day.groups.flatMap(g=>{const groupRows=(g.rows||[]).filter(r=>r.service||r.rank||r.personnel);return groupRows.map(r=>`<tr><td>${cellText(r.service)}</td><td>${cellText([r.rank,r.personnel].filter(Boolean).join(' '))}</td></tr>`)});return `<section class="adit-day-print ${index?'adit-day-continuation':''}"><h3 class="adit-day-title">Para o dia ${esc(longDate(day.date))}</h3><table class="adit-scale"><colgroup><col style="width:35%"><col style="width:65%"></colgroup><thead><tr><th>Serviço</th><th>Militar(es)</th></tr></thead><tbody>${rows.join('')||'<tr><td colspan="2">Escala não informada.</td></tr>'}<tr><td><b>Parada Diária</b></td><td><b>Horário:</b> ${cellText(d.paradeTime)}<br><b>Local:</b> ${cellText(d.paradeLocation)}</td></tr></tbody></table></section>`;}).join(''),partMarkup=parts.map(([key,title])=>{const items=(notices[key]||[]).filter(n=>n.title||n.body);return `<section class="adit-part"><h3>${title}</h3>${items.length?items.map(n=>`<div class="adit-notice-print"><strong>${cellText(n.title)}</strong>${n.body?`<p>${cellText(n.body)}</p>`:''}</div>`).join(''):'<p class="adit-no-change">Sem Alteração</p>'}</section>`;}).join(''),signerRole=d.mainResponding?'Resp. Sargenteante da 3ª Bateria de Obuses':'Sargenteante da 3ª Bateria de Obuses',commanderRole=d.commanderResponding?'Resp. Comandante da 3ª Bateria de Obuses':'Comandante da 3ª Bateria de Obuses';return `<article class="paper paper-aditamento"><div class="paper-header"><strong>MINISTÉRIO DA DEFESA</strong><strong>EXÉRCITO BRASILEIRO</strong><strong>25º GRUPO DE ARTILHARIA DE CAMPANHA</strong><strong>(C Art Cav/1831)</strong><strong>GRUPO LEITE DE CASTRO</strong><strong>3ª BATERIA DE OBUSES</strong></div><h2 class="paper-title">ADITAMENTO AO BOLETIM INTERNO Nr ${esc(doc.bulletin_number)} DE ${esc(longDate(d.bulletinDate||doc.document_date,false).toUpperCase())}</h2><p class="paper-intro">PARA CONHECIMENTO DESTA BATERIA E DEVIDA EXECUÇÃO PUBLICO O SEGUINTE:</p><h3 class="adit-part-title">1ª PARTE – SERVIÇOS DIÁRIOS</h3>${dayMarkup}${partMarkup}<div class="paper-signature adit-signature"><strong>${cellText(d.mainSigner)}</strong><span>${signerRole}</span></div><div class="paper-signature adit-signature adit-commander-signature"><strong>${cellText(d.commander)}</strong><span>${commanderRole}</span></div></article>`;}
  function renderDocumentMarkup(doc){if(doc.kind==='pernoite')return pernoiteMarkup(doc);if(doc.kind==='aditamento')return aditamentoMarkup(doc);const d=doc.data||{},header=`<div class="paper-header"><strong>MINISTÉRIO DA DEFESA</strong><strong>EXÉRCITO BRASILEIRO</strong><strong>${cellText(d.unit||'25º GRUPO DE ARTILHARIA DE CAMPANHA')}</strong><span>(Organização Militar)</span><strong>GRUPO LEITE DE CASTRO</strong><strong>${cellText(d.subunit||'3ª BATERIA DE OBUSES')}</strong></div>`;
    if(doc.kind==='fatd'){const authority=[d.authorityRank,d.authorityName].filter(Boolean).join(' '),military=[d.militaryName,d.militaryRank].filter(Boolean).join(' - '),participant=[d.participantName,d.participantRank].filter(Boolean).join(' — '),blankLines=count=>Array.from({length:count},()=>'<div class="fatd-writing-line"></div>').join(''),fatdDate=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${d.date||doc.document_date}T12:00:00`)).replace(/\sde\s/g,' ').replace(/\./g,'').toUpperCase();return `<div class="fatd-document"><article class="paper fatd-page fatd-page-one"><div class="fatd-emblem"><img src="${location.origin}/fatd-emblem.png" alt="Símbolo Nacional presente no modelo fornecido"></div><div class="fatd-heading"><strong>MINISTÉRIO DA DEFESA</strong><strong>EXÉRCITO BRASILEIRO</strong><strong>25º GRUPO DE ARTILHARIA DE CAMPANHA</strong><strong>(Corpo de Artilharia a Cavalo/1831)</strong><strong>GRUPO LEITE DE CASTRO</strong></div><h2 class="fatd-title">FORMULÁRIO DE APURAÇÃO DE TRANSGRESSÃO DISCIPLINAR</h2><div class="fatd-process-row"><span><b>PROCESSO Nº:</b> ${cellText(doc.bulletin_number)}</span><span><b>DATA:</b> ${esc(fatdDate)}</span></div><section class="fatd-section fatd-identification"><h3>IDENTIFICAÇÃO DO MILITAR</h3><div><b>Grau Hierárquico:</b> ${cellText(d.militaryRank)} <b class="fatd-right-label">IDT/CPF:</b> ${cellText(d.militaryId)}</div><div><b>Nome Completo:</b> ${cellText(d.militaryName)}</div><div><b>Subunidade/OM:</b> ${cellText(d.militarySubunit)}</div></section><section class="fatd-section fatd-identification"><h3>IDENTIFICAÇÃO DO PARTICIPANTE</h3><div><b>Grau Hierárquico:</b> ${cellText(d.participantRank)} <b class="fatd-right-label">NR/IDT:</b> ${cellText(d.participantId)}</div><div><b>Nome Completo:</b> ${cellText(d.participantName)}</div><div><b>Subunidade/OM:</b> ${cellText(d.participantSubunit)}</div></section><section class="fatd-section fatd-report"><h3>RELATO DO FATO</h3><p>${cellText(d.report)}</p><div class="fatd-participant-sign">${cellText(participant)}</div></section><section class="fatd-section fatd-awareness"><h3>CIENTE DO MILITAR ARROLADO</h3><p>Declaro que tenho conhecimento de que me está sendo imputada a autoria do fato acima e me foi concedido o prazo de três dias úteis, para apresentar, por escrito, as minhas justificativas ou razões de defesa.</p><div class="fatd-date-printed"><b>Data:</b> &nbsp; ____ &nbsp; de &nbsp; ______________ &nbsp; de ${esc((d.date||doc.document_date||'').slice(0,4))}</div><div class="fatd-military-sign">${cellText(military)}</div></section></article><article class="paper fatd-page fatd-page-two"><section class="fatd-defense"><h3>JUSTIFICATIVAS / RAZÕES DE DEFESA</h3><div class="fatd-lines">${blankLines(13)}</div><p class="fatd-hand-date">DATA: &nbsp;____ / ____ / ______</p><div class="fatd-military-sign">${cellText(military)}</div></section><section class="fatd-decision"><h3>DECISÃO DA AUTORIDADE COMPETENTE PARA APLICAR A PUNIÇÃO DISCIPLINAR.</h3><div class="fatd-lines">${blankLines(8)}</div><p class="fatd-hand-date">DATA: ____ / ____ / ______</p><div class="fatd-authority-sign"><strong>${cellText(authority)}</strong>${d.authorityRole?`<span>${cellText(d.authorityRole)}</span>`:''}${d.authoritySubunit?`<span>${cellText(d.authoritySubunit)}</span>`:''}</div><p class="fatd-publication">PUNIÇÃO PUBLICADA NO BI nº ________, de ______ de __________________ de __________.</p></section></article></div>`;}
    const rowHtml=(r)=>`<tr><th>${cellText(r.rank)}</th><td>${r.description?`<b>${cellText(r.description)}:</b> `:''}${cellText(r.personnel)}</td><td>${Number(r.count)||0}</td></tr>`,sum=rows=>(rows||[]).reduce((n,r)=>n+(Number(r.count)||0),0),inTotal=sum(d.formation),outTotal=sum(d.destinations),grand=inTotal+outTotal;
    return `<article class="paper paper-pernoite"><div class="pernoite-top"><aside><i>VISTO:</i><div class="signature-line">${cellText(d.commander)}</div><small>${cellText(d.commanderRole)}</small></aside>${header}</div><div class="pernoite-unit">${cellText(d.subunit||'3ª BATERIA DE OBUSES')}</div><h2 class="pernoite-title">REVISTA DO RECOLHER DO DIA ${esc(longDate(d.serviceDate))}</h2><p class="paper-center bulletin-ref">Boletim Interno Nr ${esc(doc.bulletin_number)} · ${esc(longDate(d.bulletinDate,false))}</p><table class="pernoite-table"><thead><tr><th>GRADUAÇÃO</th><th>EM FORMA</th><th>SOMA</th></tr></thead><tbody>${(d.formation||[]).map(rowHtml).join('')}<tr class="total-row"><th colspan="2">TOTAL</th><td>${inTotal}</td></tr></tbody></table><table class="pernoite-table destinations"><thead><tr><th>GRADUAÇÃO</th><th>OUTROS DESTINOS</th><th>SOMA</th></tr></thead><tbody>${(d.destinations||[]).map(rowHtml).join('')}<tr class="total-row"><th colspan="2">TOTAL</th><td>${outTotal}</td></tr><tr class="state-row"><th colspan="2">ESTADO DO EFETIVO</th><td>${grand}</td></tr></tbody></table><p class="paper-center location-date">${cellText(d.city)}, ${esc(longDate(d.serviceDate,false))}.</p><div class="paper-signature"><strong>${cellText(d.mainSigner)}</strong><span>${cellText(d.mainRole)}</span></div><table class="review-box"><tbody><tr><th colspan="2">REVISTA DO RECOLHER ______ ALTERAÇÃO</th></tr><tr><td class="review-stamp">Visto:</td><td>Quartel em ${cellText(d.city)}, ____ de ______________ de ______.</td></tr><tr><td class="review-stamp">OF DE DIA</td><td>${cellText(d.officerOfDay)}<br><br>______________________________ &nbsp; Sgt de Dia: ${cellText(d.sergeantOfDay)}</td></tr><tr><td class="review-stamp">OBSERVAÇÕES</td><td>${cellText(d.observations)}</td></tr></tbody></table></article>`;
  }
  async function deleteRecord(kind,id){const labels={document:'documento','force-map':'Mapa da Força',scale:'escala de serviço',vacation:'período de férias','unit-person':'cadastro do efetivo',user:'usuário',task:'tarefa'},label=labels[kind];if(!label)return;let message=`Excluir este ${label}? Esta ação não pode ser desfeita.`;if(kind==='unit-person')message='Excluir esta ficha do efetivo? Os períodos de férias associados e a participação desta pessoa nas escalas também serão removidos.';if(kind==='user'&&systemUsers.find(x=>x.id===Number(id))?.display_name===user)message='Esse usuário está conectado e não pode ser excluído.';if(kind==='user'&&systemUsers.find(x=>x.id===Number(id))?.display_name===user){notify(message);return;}if(!window.confirm(message))return;try{if(kind==='task'){data.tasks=data.tasks.filter(t=>t.id!==id);data.notifications=data.notifications.filter(n=>n.taskId!==id);save();render();renderInbox();closeModal();notify('Tarefa excluída.');return;}const paths={document:`/api/documents/${id}`,'force-map':`/api/force-maps/${id}`,scale:`/api/service-scales/${id}`,vacation:`/api/vacation-plan/${id}`,'unit-person':`/api/unit-personnel/${id}`,user:`/api/users/${id}`};await api(paths[kind],{method:'DELETE'});if(kind==='document'){documents=documents.filter(x=>x.id!==Number(id));renderDocuments();}else if(kind==='force-map'){forceMaps=forceMaps.filter(x=>x.id!==Number(id));renderForceMaps();}else if(kind==='scale'){serviceScales=serviceScales.filter(x=>x.id!==Number(id));if(selectedScale?.id===Number(id)){selectedScale=null;$('#scale-board').classList.add('hidden');}renderScaleList();}else if(kind==='vacation'){vacationPeriods=vacationPeriods.filter(x=>x.id!==Number(id));renderVacation();await loadNotices();render();}else if(kind==='unit-person'){unitPersonnel=unitPersonnel.filter(x=>x.id!==Number(id));vacationPeriods=vacationPeriods.filter(x=>x.person_id!==Number(id));serviceScales=serviceScales.map(s=>({...s,participants:s.participants.filter(p=>p.id!==Number(id)),assignments:Object.fromEntries(Object.entries(s.assignments).filter(([key])=>Number(key.split('|')[0])!==Number(id)))}));if(selectedScale){selectedScale=serviceScales.find(s=>s.id===selectedScale.id)||null;if(selectedScale)renderScaleBoard();}renderUnitRoster();await loadNotices();render();}else if(kind==='user'){systemUsers=systemUsers.filter(x=>x.id!==Number(id));renderPersonnel();}closeModal();notify(`${label.charAt(0).toUpperCase()+label.slice(1)} excluído.`);}catch(error){notify(error.message||`Não foi possível excluir ${label}.`);}}
  function printDocument(id){const doc=documents.find(x=>x.id===Number(id));if(!doc)return;let markup;try{markup=renderDocumentMarkup(doc);}catch(error){console.error('Falha ao montar documento para impressão:',error);notify('Não foi possível preparar a impressão deste documento. Verifique os dados salvos e tente novamente.');return;}const old=document.querySelector('#sigase-print-host');if(old)old.remove();const host=document.createElement('main');host.id='sigase-print-host';host.innerHTML=`<style>${printStyles}@media screen{#sigase-print-host{display:none!important}}@media print{html,body{width:auto!important;height:auto!important;overflow:visible!important;background:#fff!important;margin:0!important;padding:0!important}body>*:not(#sigase-print-host){display:none!important}#sigase-print-host{display:block!important;position:static!important;visibility:visible!important;opacity:1!important;width:auto!important;height:auto!important;overflow:visible!important;background:#fff!important;color:#111!important;padding:0!important;margin:0!important}}</style>${markup}`;document.body.appendChild(host);const cleanup=()=>{host.remove();window.removeEventListener('afterprint',cleanup);};window.addEventListener('afterprint',cleanup,{once:true});try{window.focus();window.print();setTimeout(cleanup,120000);}catch(error){cleanup();console.error('Falha ao iniciar impressão:',error);notify('Não foi possível abrir a impressão. Tente novamente.');}}
  async function loadScales(){try{const result=await api('/api/service-scales');serviceScales=result.scales;renderScaleList();if(selectedScale){selectedScale=serviceScales.find(s=>s.id===selectedScale.id)||null;if(selectedScale)renderScaleBoard();else $('#scale-board').classList.add('hidden');}}catch(error){$('#scale-list').innerHTML=empty('Escalas indisponíveis',esc(error.message));}}
  function renderScaleList(){const list=$('#scale-list');list.innerHTML=serviceScales.length?serviceScales.map(s=>`<div class="scale-list-item"><button class="scale-list-card ${selectedScale?.id===s.id?'active':''}" data-scale-open="${s.id}"><span class="scale-list-icon">▥</span><span class="scale-list-text"><strong>${esc(s.name)}</strong><small>${scaleModeName(s.mode)} · ${s.participants.length} militares · ${s.services.length} serviços</small></span><span class="scale-list-arrow">›</span></button>${canManageUsers?`<button class="button delete-button" data-delete-kind="scale" data-delete-id="${s.id}">Excluir</button>`:''}</div>`).join(''):empty('Nenhuma escala criada','Crie uma escala para começar.');}
  const scaleModeName=mode=>mode==='corrida'?'Escala corrida':mode==='preta_vermelha'?'Preta e vermelha':'Completa · preta, vermelha e roxa';
  function openScale(id){selectedScale=serviceScales.find(s=>s.id===Number(id))||null;if(!selectedScale)return;scaleMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);renderScaleList();renderScaleBoard();}
  function dayISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function scaleDayClass(day){if(selectedScale.mode==='corrida')return 'day-black';const date=dayISO(day);if(selectedScale.red_dates.includes(date)||day.getDay()===0||day.getDay()===6)return 'day-red';if(selectedScale.mode==='completa'&&day.getDay()===5)return 'day-purple';return 'day-black';}
  function scaleCategory(day){if(selectedScale.mode==='corrida')return 'corrida';const iso=dayISO(day);if(selectedScale.red_dates.includes(iso)||day.getDay()===0||day.getDay()===6)return 'vermelha';if(selectedScale.mode==='completa'&&day.getDay()===5)return 'roxa';return 'preta';}
  function renderScaleBoard(){if(!selectedScale)return;const s=selectedScale;$('#scale-board').classList.remove('hidden');$('#scale-kind-label').textContent=scaleModeName(s.mode).toUpperCase();$('#scale-board-title').textContent=s.name;$('#scale-board-meta').textContent=`${s.participants.length} militares · ${s.services.map(x=>`${x.name}: ${x.daily_slots}/dia`).join(' · ')}`;$('#edit-scale').classList.toggle('hidden',!canEditPersonnel);$('#scale-month').textContent=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(scaleMonth);const first=new Date(scaleMonth.getFullYear(),scaleMonth.getMonth(),1),last=new Date(scaleMonth.getFullYear(),scaleMonth.getMonth()+1,0),firstISO=dayISO(first),lastISO=dayISO(last),days=Array.from({length:last.getDate()},(_,i)=>new Date(first.getFullYear(),first.getMonth(),i+1));const headers=days.map(day=>{const iso=dayISO(day),override=s.red_dates.includes(iso),defaultRed=s.mode!=='corrida'&&(day.getDay()===0||day.getDay()===6),counts=s.services.map(service=>{const count=Object.entries(s.assignments).filter(([key,value])=>key.endsWith(`|${iso}`)&&value===service.name).length;return `${esc(service.name)} ${count}/${service.daily_slots}`;}).join(' · ');return `<th class="${scaleDayClass(day)}"><div class="scale-day-heading"><span>${day.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</span><strong>${day.getDate()}</strong>${s.mode!=='corrida'?`<button class="day-type-button ${override?'is-marked':''}" data-date-type="${iso}" title="${defaultRed?'Vermelha pelo fim de semana':override?'Remover marcação vermelha':'Marcar dia como vermelho'}" ${defaultRed&&!override?'disabled':''}>${defaultRed&&!override?'FIM DE SEMANA':override?'VERMELHA · ×':'＋ VERMELHA'}</button>`:''}<em>${counts}</em></div></th>`;}).join('');const rows=s.participants.map(p=>{const assignments=Object.fromEntries(Object.entries(s.assignments).filter(([key])=>key.startsWith(`${p.id}|`)).map(([key,value])=>[key.slice(String(p.id).length+1),value]));const historyStart=new Date(first);historyStart.setDate(first.getDate()-800);let earliest=historyStart;for(const dateText of Object.keys(assignments)){if(dateText>=dayISO(historyStart)&&dateText<firstISO&&dateObj(dateText)<earliest)earliest=dateObj(dateText);}const counters={corrida:99,preta:99,vermelha:99,roxa:99},display={};for(let d=new Date(earliest);d<=last;d.setDate(d.getDate()+1)){const iso=dayISO(d),category=scaleCategory(d),service=assignments[iso]||'';if(service)counters[category]=0;else counters[category]=Math.min(99,counters[category]+(counters[category]<99?1:0));if(iso>=firstISO&&iso<=lastISO)display[iso]=service||String(counters[category]);}const cells=days.map(day=>{const iso=dayISO(day),value=display[iso]||'99',service=assignments[iso]||'',title=service?`Serviço: ${service}`:`${value} dia(s) de folga na categoria ${scaleCategory(day)}`;return `<td class="${scaleDayClass(day)}"><button class="scale-cell ${service?'has-duty':''} ${value==='99'?'rest-limit':''}" data-scale-cell="${p.id}|${iso}" title="${title}" ${canEditPersonnel?'':'disabled'}>${esc(value)}</button></td>`;}).join('');return `<tr><th class="scale-person-sticky"><strong>${esc(p.rank)}</strong><span>${esc(p.war_name)}</span></th>${cells}</tr>`;}).join('');$('#scale-schedule').innerHTML=`<div class="scale-table-scroll"><table class="scale-table"><thead><tr><th class="scale-person-sticky scale-person-head">POSTO / NOME DE GUERRA</th>${headers}</tr></thead><tbody>${rows}</tbody></table></div>`;renderNextServiceReport();}
  function renderNextServiceReport(){const scale=selectedScale;if(!scale)return;const cursor=new Date(today());cursor.setDate(cursor.getDate()+1);const reportDates=[new Date(cursor)];if(scale.mode!=='corrida'&&scaleCategory(cursor)==='vermelha'){let steps=0;while(scaleCategory(cursor)==='vermelha'&&steps<14){cursor.setDate(cursor.getDate()+1);steps++;if(scaleCategory(cursor)==='vermelha')reportDates.push(new Date(cursor));}reportDates.push(new Date(cursor));}const todayText=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(today());$('#next-service-caption').textContent=`Hoje é ${todayText}. O período inclui amanhã e se estende pelos dias vermelhos consecutivos até o próximo dia comum.`;$('#next-service-dates').innerHTML=reportDates.map(day=>{const iso=dayISO(day),items=scale.participants.map(p=>({person:p,service:scale.assignments[`${p.id}|${iso}`]})).filter(x=>x.service);return `<article class="next-service-day"><h4>${new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(day)}</h4>${items.length?items.map(x=>`<div class="next-service-person"><strong>${esc(x.person.rank)} ${esc(x.person.war_name)}</strong><span>${esc(x.service)}</span></div>`).join(''):'<p class="muted">Nenhum serviço atribuído.</p>'}</article>`;}).join('');}
  function scaleForm(scale=null){const editing=!!scale;api('/api/unit-personnel').then(roster=>{unitPersonnel=roster.personnel;const services=scale?.services||[{name:'Plantão',daily_slots:1},{name:'Guarda',daily_slots:1},{name:'Vila',daily_slots:1}],chosen=new Set((scale?.participants||[]).map(p=>p.id));showModal(`<div class="modal-head"><div><h2>${editing?'Editar configuração':'Criar escala'}</h2><p>Defina a regra, os serviços e os militares participantes.</p></div><button class="close-button" data-close>×</button></div><form id="scale-form" novalidate><div class="form-body"><div class="form-field"><label for="scale-name">Nome da escala *</label><input id="scale-name" maxlength="80" value="${esc(scale?.name||'')}" placeholder="Ex.: Plantões e guardas"><small class="error" data-error="scale-name"></small></div><div class="form-field"><label for="scale-mode">Divisão da escala *</label><select id="scale-mode"><option value="corrida" ${scale?.mode==='corrida'?'selected':''}>Escala corrida — não diferencia dias</option><option value="preta_vermelha" ${scale?.mode==='preta_vermelha'?'selected':''}>Preta e vermelha — segunda a sexta / fim de semana</option><option value="completa" ${scale?.mode==='completa'?'selected':''}>Completa — sexta roxa, sábado e domingo vermelhos</option></select><small class="form-hint">Em escalas por cor, é possível marcar feriados e outros dias como vermelhos diretamente no cabeçalho do calendário.</small></div><div class="form-field"><div class="scale-form-section-head"><label>Serviços e quantidade necessária por dia *</label><button type="button" class="text-button" id="add-scale-service">＋ Adicionar serviço</button></div><div id="scale-services-fields">${services.map((service,i)=>scaleServiceField(service,i)).join('')}</div><small class="error" data-error="services"></small></div><div class="form-field"><div class="scale-form-section-head"><label>Militares que concorrem *</label><span id="scale-selected-count" class="muted"></span></div><input id="scale-person-search" class="scale-person-search" placeholder="Filtrar por nome, guerra ou posto..."><div id="scale-participant-list" class="scale-participant-list">${unitPersonnel.map(p=>`<label class="scale-participant"><input type="checkbox" value="${p.id}" ${chosen.has(p.id)?'checked':''}><span><strong>${esc(p.rank)} ${esc(p.war_name)}</strong><small>${esc(p.full_name)}</small></span></label>`).join('')}</div><small class="error" data-error="participants"></small></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button primary">${editing?'Salvar configuração':'Criar escala'}</button></div></form>`,true);const updateCount=()=>{$('#scale-selected-count').textContent=`${$('#scale-participant-list').querySelectorAll('input:checked').length} selecionados`;};updateCount();$('#scale-person-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.scale-participant').forEach(label=>label.classList.toggle('hidden',!label.textContent.toLowerCase().includes(q)));});$('#scale-participant-list').addEventListener('change',updateCount);$('#add-scale-service').addEventListener('click',()=>{const host=$('#scale-services-fields');host.insertAdjacentHTML('beforeend',scaleServiceField({name:'',daily_slots:1},host.querySelectorAll('.scale-service-row').length));});$('#scale-services-fields').addEventListener('click',e=>{const remove=e.target.closest('[data-remove-service]');if(remove){remove.closest('.scale-service-row').remove();}});$('#scale-form').addEventListener('submit',async e=>{e.preventDefault();const name=$('#scale-name').value.trim(),services=[...$('#scale-services-fields').querySelectorAll('.scale-service-row')].map(row=>({name:row.querySelector('[data-service-name]').value.trim(),daily_slots:Number(row.querySelector('[data-service-slots]').value)})),participants=[...$('#scale-participant-list').querySelectorAll('input:checked')].map(x=>Number(x.value));$('[data-error="scale-name"]').textContent=name?'':'Informe o nome da escala.';$('[data-error="services"]').textContent=services.length&&services.every(x=>x.name&&x.daily_slots>0)?'':'Informe nome e quantidade para cada serviço.';$('[data-error="participants"]').textContent=participants.length?'':'Selecione ao menos um militar.';if(!name||!services.length||services.some(x=>!x.name||!x.daily_slots)||!participants.length)return;try{const payload={name,mode:$('#scale-mode').value,services,participants};const result=await api(editing?`/api/service-scales/${scale.id}`:'/api/service-scales',{method:editing?'PUT':'POST',body:JSON.stringify(payload)});if(editing)serviceScales=serviceScales.map(s=>s.id===scale.id?result.scale:s);else serviceScales.push(result.scale);selectedScale=result.scale;closeModal();renderScaleList();renderScaleBoard();notify(editing?'Configuração atualizada.':'Escala criada.');}catch(error){notify(error.message);}});}).catch(error=>notify(error.message));}
  function scaleServiceField(service,index){return `<div class="scale-service-row"><input data-service-name maxlength="40" value="${esc(service.name)}" placeholder="Nome do serviço"><label>Vagas/dia <input data-service-slots type="number" min="1" max="100" value="${service.daily_slots}"></label><button type="button" class="remove-row" data-remove-service aria-label="Remover serviço">×</button></div>`;}
  function editScaleCell(key){const [personId,date]=key.split('|'),person=selectedScale.participants.find(p=>p.id===Number(personId)),current=selectedScale.assignments[key]||'';if(!person)return;showModal(`<div class="modal-head"><div><p class="eyebrow">${esc(person.rank)} ${esc(person.war_name)}</p><h2>${fmt(date)}</h2><p>Escolha o serviço deste militar para o dia.</p></div><button class="close-button" data-close>×</button></div><form id="scale-cell-form"><div class="form-body"><div class="form-field"><label for="scale-cell-service">Serviço / situação</label><select id="scale-cell-service"><option value="">Folga / sem serviço</option>${selectedScale.services.map(s=>`<option value="${esc(s.name)}" ${current===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button primary">Salvar célula</button></div></form>`);$('#scale-cell-form').addEventListener('submit',async e=>{e.preventDefault();try{const service=$('#scale-cell-service').value;await api(`/api/service-scales/${selectedScale.id}/cell`,{method:'POST',body:{person_id:Number(personId),date,service:service||null}});const k=`${personId}|${date}`;if(service)selectedScale.assignments[k]=service;else delete selectedScale.assignments[k];closeModal();renderScaleBoard();}catch(error){notify(error.message);}});}
  async function toggleRedDate(date){if(!selectedScale||selectedScale.mode==='corrida')return;const is_red=!selectedScale.red_dates.includes(date);try{await api(`/api/service-scales/${selectedScale.id}/date-type`,{method:'POST',body:{date,is_red}});selectedScale.red_dates=is_red?[...selectedScale.red_dates,date]:selectedScale.red_dates.filter(d=>d!==date);renderScaleBoard();}catch(error){notify(error.message);}}
  async function loadVacation(){try{const [result,roster]=await Promise.all([api('/api/vacation-plan'),api('/api/unit-personnel')]);vacationPeriods=result.periods;unitPersonnel=roster.personnel;renderVacation();}catch(error){$('#vacation-list').innerHTML=empty('Plano indisponível',esc(error.message));}}
  const vacationFmt=value=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(dateObj(value)).replace('.','');
  function vacationCard(p){return `<article class="vacation-card"><div class="vacation-date-block"><strong>${dateObj(p.start_date).getDate()}</strong><span>${new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(dateObj(p.start_date)).replace('.','')}</span></div><div class="vacation-main"><strong>${esc(p.rank)} ${esc(p.full_name)}</strong><span>Período ${p.period_number}/${p.period_total} · ${p.vacation_days} dias · ${vacationFmt(p.start_date)} a ${vacationFmt(p.end_date)}</span><small>Apresentação: ${vacationFmt(p.presentation_date)}${p.travel_days?' · inclui 2 dias de deslocamento':''}</small></div><div class="vacation-actions">${canEditPersonnel?`<button class="button secondary" data-vacation-edit="${p.id}">Editar</button><button class="button delete-button" data-delete-kind="vacation" data-delete-id="${p.id}">Excluir</button>`:''}</div></article>`;}
  function renderVacation(){const filtered=vacationPeriods.filter(p=>`${p.full_name} ${p.rank}`.toLowerCase().includes(vacationSearch.toLowerCase())),todayISO=dayISO(today());$('#vacation-count').textContent=`${filtered.length} ${filtered.length===1?'período cadastrado':'períodos cadastrados'}`;if(!vacationPeriods.length){$('#vacation-list').innerHTML=empty('Nenhum período cadastrado','Inclua períodos de férias para visualizá-los aqui e no calendário.');renderCalendar();return;}const groups=[['previous','Anteriores',p=>p.presentation_date<=todayISO],['current','Atuais',p=>p.start_date<=todayISO&&p.presentation_date>todayISO],['future','Futuros',p=>p.start_date>todayISO]];$('#vacation-list').innerHTML=groups.map(([key,label,matches])=>{const items=filtered.filter(matches).sort((a,b)=>a.start_date.localeCompare(b.start_date)||a.full_name.localeCompare(b.full_name,'pt-BR'));return `<details class="vacation-folder ${key==='current'&&items.length?'vacation-folder-current':''}" ${key==='current'&&items.length?'open':''}><summary><span class="folder-icon">▰</span><strong>${label}</strong><small>${items.length} ${items.length===1?'período':'períodos'}</small></summary><div class="vacation-folder-content">${items.length?items.map(vacationCard).join(''):empty('Nenhum período nesta pasta',key==='previous'?'Períodos cujo retorno já ocorreu aparecerão aqui.':key==='current'?'Militares em férias ou em deslocamento aparecerão aqui.':'Próximos períodos de férias aparecerão aqui.')}</div></details>`;}).join('');renderCalendar();}
  function renderCalendar(){const year=calendarDate.getFullYear(),month=calendarDate.getMonth(),first=new Date(year,month,1),start=new Date(year,month,1-first.getDay());$('#calendar-month').textContent=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(first);const names=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];let html=names.map(n=>`<div class="calendar-weekday">${n}</div>`).join('');for(let i=0;i<42;i++){const day=new Date(start);day.setDate(start.getDate()+i);const iso=`${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`,periods=vacationPeriods.filter(p=>iso>=p.start_date&&iso<=p.end_date),starts=periods.filter(p=>iso===p.start_date);html+=`<div class="calendar-day ${day.getMonth()!==month?'outside':''} ${iso===new Date().toISOString().slice(0,10)?'today-cell':''}"><span>${day.getDate()}</span>${starts.slice(0,2).map(p=>`<small title="${esc(p.rank)} ${esc(p.full_name)}">${esc(p.full_name.split(' ').slice(-1)[0])}</small>`).join('')}${periods.length&&!starts.length?'<i class="vacation-dot"></i>':''}</div>`;}$('#vacation-calendar').innerHTML=html;}
  function vacationForm(period=null){const editing=!!period;const options=unitPersonnel.map(p=>`<option value="${p.id}" ${period?.person_id===p.id?'selected':''}>${esc(p.rank)} ${esc(p.full_name)}</option>`).join('');showModal(`<div class="modal-head"><div><h2>${editing?'Editar período de férias':'Incluir período de férias'}</h2><p>Selecione uma ficha do efetivo da unidade.</p></div><button class="close-button" data-close>×</button></div><form id="vacation-form" novalidate><div class="form-body"><div class="form-field"><label for="vacation-person">Militar *</label><select id="vacation-person" name="person_id"><option value="">Selecione uma pessoa</option>${options}</select><small class="error" data-error="person"></small></div><div class="form-row"><div class="form-field"><label for="vacation-start">Início das férias *</label><input id="vacation-start" type="date" value="${esc(period?.start_date||'')}"><small class="error" data-error="start"></small></div><div class="form-field"><label for="vacation-end">Término das férias *</label><input id="vacation-end" type="date" value="${esc(period?.end_date||'')}"><small class="error" data-error="end"></small></div></div><div class="form-row"><div class="form-field"><label for="vacation-travel">Dois dias de deslocamento</label><select id="vacation-travel"><option value="0" ${!period?.travel_days?'selected':''}>Não</option><option value="1" ${period?.travel_days?'selected':''}>Sim</option></select></div><div class="form-field"><label>Dias de férias</label><input id="vacation-days" value="Calculado pelas datas" disabled></div></div><div class="form-row"><div class="form-field"><label for="vacation-period-number">Período</label><select id="vacation-period-number"></select></div><div class="form-field"><label for="vacation-period-total">Quantidade de parcelas</label><select id="vacation-period-total"><option value="1">1 período</option><option value="2">2 períodos</option><option value="3">3 períodos</option></select></div></div><div class="form-field"><label>Data de apresentação calculada</label><input id="vacation-presentation" disabled></div><p class="form-hint">O cálculo inclui as datas inicial e final; apresentação ocorre no dia seguinte ao término, somando 2 dias quando houver deslocamento.</p></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button primary">${editing?'Salvar alterações':'Salvar período'}</button></div></form>`,false);const total=$('#vacation-period-total'),number=$('#vacation-period-number');total.value=String(period?.period_total||1);const fillNumbers=()=>{const n=Number(total.value),selected=Math.min(Number(period?.period_number||1),n);number.innerHTML=Array.from({length:n},(_,i)=>`<option value="${i+1}" ${i+1===selected?'selected':''}>Período ${i+1}/${n}</option>`).join('');};fillNumbers();total.addEventListener('change',fillNumbers);const update=()=>{const a=$('#vacation-start').value,b=$('#vacation-end').value;if(a&&b&&b>=a){$('#vacation-days').value=Math.round((dateObj(b)-dateObj(a))/86400000)+1;const presentation=dateObj(b);presentation.setDate(presentation.getDate()+1+Number($('#vacation-travel').value)*2);$('#vacation-presentation').value=vacationFmt(`${presentation.getFullYear()}-${String(presentation.getMonth()+1).padStart(2,'0')}-${String(presentation.getDate()).padStart(2,'0')}`);}else{$('#vacation-days').value='—';$('#vacation-presentation').value='—';}};['vacation-start','vacation-end','vacation-travel'].forEach(id=>$('#'+id).addEventListener('change',update));update();$('#vacation-form').addEventListener('submit',async e=>{e.preventDefault();const personId=Number($('#vacation-person').value),start=$('#vacation-start').value,end=$('#vacation-end').value;[['person',personId?'':'Selecione uma pessoa.'],['start',start?'':'Informe a data inicial.'],['end',!end?'Informe a data final.':end<start?'O término não pode ser anterior ao início.':'']].forEach(([key,msg])=>$(`[data-error="${key}"]`).textContent=msg);if(!personId||!start||!end||end<start)return;const body={person_id:personId,start_date:start,end_date:end,travel_days:$('#vacation-travel').value==='1',period_number:Number(number.value),period_total:Number(total.value)};try{const result=await api(editing?`/api/vacation-plan/${period.id}`:'/api/vacation-plan',{method:editing?'PUT':'POST',body:JSON.stringify(body)});if(editing)vacationPeriods=vacationPeriods.map(p=>p.id===period.id?result.period:p);else vacationPeriods.push(result.period);closeModal();await Promise.all([loadVacation(),loadNotices()]);render();notify(editing?'Período atualizado e avisos sincronizados.':'Período salvo; avisos de início e apresentação criados.');}catch(error){notify(error.message);}});}
