  function openCreate(){
    const options=systemUsers.map(p=>`<option value="${esc(p.display_name)}">${esc(p.display_name)}</option>`).join('');
    const cats=taskCategories.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}</option>`).join('');
    showModal(`<div class="modal-head"><div><h2>Nova tarefa</h2><p>Encaminhe uma demanda para a equipe.</p></div><button class="close-button" data-close>×</button></div><form id="task-form" novalidate><div class="form-body"><div class="form-field"><label for="title">Título *</label><input id="title" name="title" maxlength="100" placeholder="Ex.: Atualizar plano de férias"><small class="error" data-error="title"></small></div><div class="form-field"><label for="description">Descrição</label><textarea id="description" name="description" maxlength="500" placeholder="Descreva o que precisa ser feito..."></textarea></div><div class="form-field"><label for="task-classification">Classificação</label><select id="task-classification"><option value="">Sem classificação</option>${cats}</select><small id="classification-suggestion" class="suggestion-note"></small></div><div class="form-field"><label for="assignee">Responsável *</label><select id="assignee" name="assignee"><option value="">Selecione uma pessoa</option>${options}</select><small class="error" data-error="assignee"></small></div><div class="form-row"><div class="form-field"><label for="priority">Prioridade</label><select id="priority"><option>Média</option><option>Alta</option><option>Baixa</option></select></div><div class="form-field"><label for="due">Prazo *</label><input id="due" type="date" min="${dayISO(today())}"><small class="error" data-error="due"></small></div></div></div><div class="modal-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button primary">Criar tarefa</button></div></form>`);
    const suggest=()=>{const category=$('#task-classification').value,matching=systemUsers.filter(candidate=>candidate.functions.includes(category));const note=$('#classification-suggestion');if(!category){note.textContent='';return;}if(!matching.length){$('#assignee').value='';note.textContent='Nenhum usuário está atribuído a esta função; selecione o responsável manualmente.';return;}$('#assignee').value=matching[0].display_name;note.textContent=`Sugestão: ${matching.map(x=>x.display_name).join(', ')} · ${matching.length===1?'responsável':'responsáveis'} por ${category}.`;};
    $('#task-classification').addEventListener('change',suggest);
    $('#task-form').addEventListener('submit',e=>{e.preventDefault();const title=$('#title').value.trim(),assignee=$('#assignee').value,due=$('#due').value;[['title',title?'':'Informe um título.'],['assignee',assignee?'':'Selecione o responsável.'],['due',!due?'Informe o prazo.':due<dayISO(today())?'O prazo não pode ser anterior a hoje.':'']].forEach(([key,msg])=>$(`[data-error="${key}"]`).textContent=msg);if(!title||!assignee||!due||due<dayISO(today()))return;const now=new Date().toISOString(),id='T-'+String(Math.max(104,...data.tasks.map(t=>Number(t.id.slice(2))||0))+1);data.tasks.unshift({id,title,description:$('#description').value.trim()||'Sem descrição.',classification:$('#task-classification').value,requester:user,assignee,priority:$('#priority').value,due,status:'Pendente',created:now,events:[['Criada',user,now]]});save();closeModal();render();renderInbox();notify('Tarefa criada com sucesso.');});
  }
  function openDetail(id){const t=data.tasks.find(x=>x.id===id);if(!t)return;const canWork=t.assignee===user&&t.status==='Pendente',canDone=t.assignee===user&&t.status!=='Concluída';showModal(`<div class="modal-head"><div><p class="eyebrow">TAREFA ${esc(t.id)}</p><h2>Detalhes da tarefa</h2></div><button class="close-button" data-close>×</button></div><div class="detail-body"><h3 class="detail-title">${esc(t.title)}</h3><p class="detail-desc">${esc(t.description)}</p><div class="detail-grid"><div><div class="detail-label">RESPONSÁVEL</div><div class="detail-value">${esc(t.assignee)}</div></div><div><div class="detail-label">SOLICITANTE</div><div class="detail-value">${esc(t.requester)}</div></div><div><div class="detail-label">PRAZO</div><div class="detail-value ${overdue(t)?'overdue-text':''}">${fmt(t.due)} ${overdue(t)?'· atrasada':''}</div></div><div><div class="detail-label">CLASSIFICAÇÃO</div><div class="detail-value">${esc(t.classification||'—')}</div></div><div><div class="detail-label">PRIORIDADE · STATUS</div><div class="detail-value"><span class="badge priority-${t.priority.toLowerCase()}">${t.priority}</span> <span class="badge status-${t.status==='Em andamento'?'andamento':t.status==='Concluída'?'concluida':'pendente'}">${t.status}</span></div></div></div><div class="history-title">Histórico de eventos</div>${[...t.events].reverse().map(([kind,who,at])=>`<div class="event"><strong>${esc(kind)}</strong><p>${esc(who)}</p><time>${dateTime(at)}</time></div>`).join('')}</div><div class="detail-actions"><button class="button secondary" data-close>Fechar</button>${canWork?`<button class="button primary" data-action="start" data-id="${esc(id)}">Iniciar tarefa</button>`:''}${canDone?`<button class="button primary" data-action="complete" data-id="${esc(id)}">${t.status==='Em andamento'?'Concluir tarefa':'Marcar como concluída'}</button>`:''}${canManageUsers?`<button class="button delete-button" data-delete-kind="task" data-delete-id="${esc(id)}">Excluir tarefa</button>`:''}</div>`);}
  function changeStatus(id,status){const t=data.tasks.find(x=>x.id===id);if(!t||t.assignee!==user)return;const now=new Date().toISOString();t.status=status;t.events.push([status==='Em andamento'?'Iniciada':'Concluída',user,now]);if(status==='Concluída'){data.notifications.unshift({id:'N-'+Date.now(),to:t.requester,taskId:t.id,text:`${user} concluiu a tarefa “${t.title}”.`,created:now,read:false});}save();closeModal();render();renderInbox();notify(status==='Concluída'?'Tarefa concluída. O solicitante recebeu uma notificação.':'Tarefa marcada como em andamento.');}
  function showNotifications(){const list=data.notifications.filter(n=>n.to===user);list.forEach(n=>n.read=true);save();render();showModal(`<div class="modal-head"><div><h2>Notificações internas</h2><p>Avisos de tarefas enviados a você neste aviso.</p></div><button class="close-button" data-close>×</button></div><div class="detail-body">${list.length?list.map(n=>`<article class="task-card" data-task="${esc(n.taskId)}"><div class="task-content"><p class="task-title">${esc(n.text)}</p><div class="task-desc">${dateTime(n.created)}</div></div></article>`).join(''):empty('Tudo em dia','Ainda não há notificações para este usuário.')}</div><div class="detail-actions"><button class="button secondary" data-close>Fechar</button></div>`);}
  function showModal(html,wide=false){$('#modal').classList.toggle('wide',wide);$('#modal').innerHTML=html;$('#modal-layer').classList.remove('hidden');}
  function closeModal(){$('#modal-layer').classList.add('hidden');$('#modal').classList.remove('wide');$('#modal').innerHTML='';}
  function notify(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
  $('#login-form').addEventListener('submit',e=>{e.preventDefault();openApp();});$('#logout-button').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST'});}catch{}$('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#notifications-button').classList.add('hidden');$('#login-password').value='';$('#login-username').value='';});
  document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
  $('#create-top').addEventListener('click',openCreate);$('#create-inbox').addEventListener('click',openCreate);$('#all-tasks').addEventListener('click',()=>view('inbox'));
  $('#search').addEventListener('input',e=>{searchTerm=e.target.value;renderInbox();$('#search').focus();$('#search').setSelectionRange(searchTerm.length,searchTerm.length);});$('#priority-filter').addEventListener('change',e=>{priorityTerm=e.target.value;renderInbox();});
  $('#add-person').addEventListener('click',()=>{if(canManageUsers)userForm();});$('#manage-categories').addEventListener('click',categoryManager);$('#person-search').addEventListener('input',e=>{personSearch=e.target.value;renderPersonnel();$('#person-search').focus();$('#person-search').setSelectionRange(personSearch.length,personSearch.length);});$('#add-unit-person').addEventListener('click',()=>{if(canEditPersonnel)unitPersonForm();});$('#unit-search').addEventListener('input',e=>{unitSearch=e.target.value;renderUnitRoster();$('#unit-search').focus();$('#unit-search').setSelectionRange(unitSearch.length,unitSearch.length);});
  $('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){activeTab=b.dataset.tab;renderInbox();}});
  $('#document-kinds').addEventListener('click',e=>{const b=e.target.closest('[data-kind]');if(b){documentKind=b.dataset.kind;documents=[];renderDocuments();loadDocuments();}});$('#new-document').addEventListener('click',()=>{if(canEditDocuments)documentForm(documentKind);});
  $('#new-force-map').addEventListener('click',async()=>{if(!canEditDocuments)return;await loadUnitRoster();if(unitPersonnel.length)forceMapForm();else notify('Cadastre pessoas no efetivo antes de criar o mapa.');});
  $('#new-vacation').addEventListener('click',async()=>{if(!canEditPersonnel)return;try{if(!unitPersonnel.length)await loadUnitRoster();if(unitPersonnel.length)vacationForm();else notify('Cadastre pessoas no efetivo antes de criar períodos.');}catch(error){notify(error.message);}});$('#vacation-search').addEventListener('input',e=>{vacationSearch=e.target.value;renderVacation();});$('#calendar-prev').addEventListener('click',()=>{calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()-1,1);renderCalendar();});$('#calendar-next').addEventListener('click',()=>{calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+1,1);renderCalendar();});$('#calendar-today').addEventListener('click',()=>{calendarDate=new Date(new Date().getFullYear(),new Date().getMonth(),1);renderCalendar();});
  $('#new-notice').addEventListener('click',()=>noticeForm());
  $('#new-scale').addEventListener('click',()=>{if(canEditPersonnel)scaleForm();});$('#edit-scale').addEventListener('click',()=>{if(canEditPersonnel&&selectedScale)scaleForm(selectedScale);});$('#scale-month-prev').addEventListener('click',()=>{scaleMonth=new Date(scaleMonth.getFullYear(),scaleMonth.getMonth()-1,1);renderScaleBoard();});$('#scale-month-next').addEventListener('click',()=>{scaleMonth=new Date(scaleMonth.getFullYear(),scaleMonth.getMonth()+1,1);renderScaleBoard();});$('#scale-month-today').addEventListener('click',()=>{scaleMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);renderScaleBoard();});
  document.addEventListener('click',e=>{const viewLink=e.target.closest('[data-view-link]');if(viewLink){view(viewLink.dataset.viewLink);return;}const noticeAck=e.target.closest('[data-notice-ack]');if(noticeAck){acknowledgeNotice(noticeAck.dataset.noticeAck);return;}const remove=e.target.closest('[data-delete-kind]');if(remove){deleteRecord(remove.dataset.deleteKind,remove.dataset.deleteId);return;}if(e.target.closest('[data-close]'))closeModal();const scaleOpen=e.target.closest('[data-scale-open]');if(scaleOpen){openScale(scaleOpen.dataset.scaleOpen);return;}const scaleCell=e.target.closest('[data-scale-cell]');if(scaleCell&&canEditPersonnel){editScaleCell(scaleCell.dataset.scaleCell);return;}const redDate=e.target.closest('[data-date-type]');if(redDate&&canEditPersonnel){toggleRedDate(redDate.dataset.dateType);return;}const vacationEdit=e.target.closest('[data-vacation-edit]');if(vacationEdit&&canEditPersonnel){const period=vacationPeriods.find(x=>x.id===Number(vacationEdit.dataset.vacationEdit));if(period)vacationForm(period);return;}const forceView=e.target.closest('[data-force-view]');if(forceView){openForceMap(forceView.dataset.forceView);return;}const forceEdit=e.target.closest('[data-force-edit]');if(forceEdit&&canEditDocuments){const map=forceMaps.find(x=>x.id===Number(forceEdit.dataset.forceEdit));if(map)forceMapForm(map);return;}const forcePrint=e.target.closest('[data-force-print]');if(forcePrint){printForceMap(forcePrint.dataset.forcePrint);return;}const docEdit=e.target.closest('[data-doc-edit]');if(docEdit&&canEditDocuments){const d=documents.find(x=>x.id===Number(docEdit.dataset.docEdit));if(d)documentForm(d.kind,d);return;}const docView=e.target.closest('[data-doc-view]');if(docView){openDocument(docView.dataset.docView);return;}const docPrint=e.target.closest('[data-doc-print]');if(docPrint){printDocument(docPrint.dataset.docPrint);return;}const unitEdit=e.target.closest('[data-unit-edit]');if(unitEdit&&canEditPersonnel){unitPersonForm(unitPersonnel.find(p=>p.id===Number(unitEdit.dataset.unitEdit)));return;}const unitView=e.target.closest('[data-unit-view]');if(unitView){unitDetail(unitView.dataset.unitView);return;}const edit=e.target.closest('[data-person-edit]');const userEdit=e.target.closest('[data-user-edit]');if(userEdit&&canManageUsers){userForm(systemUsers.find(p=>p.id===Number(userEdit.dataset.userEdit)));return;}const person=e.target.closest('[data-person-view]');if(person){personDetail(person.dataset.personView);return;}const task=e.target.closest('[data-task]');if(task)openDetail(task.dataset.task);const act=e.target.closest('[data-action]');if(act)changeStatus(act.dataset.id,act.dataset.action==='start'?'Em andamento':'Concluída');});
  $('#modal-layer').addEventListener('click',e=>{if(e.target.id==='modal-layer')closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  const notifButton=document.createElement('button');notifButton.id='notifications-button';notifButton.className='icon-button hidden';notifButton.title='Notificações';notifButton.setAttribute('aria-label','Notificações internas');notifButton.textContent='♧';notifButton.style.cssText='position:fixed;right:23px;top:78px;background:#fff;border:1px solid #e8ebe7;border-radius:50%;width:35px;height:35px;color:#506452;z-index:3;font-size:16px';notifButton.addEventListener('click',showNotifications);document.body.appendChild(notifButton);
